export class Sound{constructor(muted=true){this.muted=muted;this.ctx=null;this.beat=0;this.timer=0}init(){if(!this.ctx)this.ctx=new(window.AudioContext||window.webkitAudioContext)();this.ctx.resume().catch(()=>{})}tone(freq,duration=.1,volume=.025){if(this.muted||!this.ctx)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type='triangle';o.frequency.value=freq;g.gain.setValueAtTime(volume,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+duration);o.connect(g).connect(this.ctx.destination);o.start();o.stop(this.ctx.currentTime+duration)}effect(kind){this.tone(({rescue:440,sale:660,flow:880,wave:330,burn:130,shout:220,reuse:780})[kind]||550,.14)}tick(dt,active){if(!active||this.muted)return;this.timer-=dt;if(this.timer<=0){this.timer=.32;this.tone([220,0,330,440,0,330,293,0,196,0,293,392,0,293,330,0][this.beat++%16],.22,.012)}}}
